import assert from 'node:assert/strict';import {chromium} from 'playwright-core';
const browser=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',args:['--disable-gpu','--no-first-run']});const page=await browser.newPage({viewport:{width:1600,height:980}});const errors=[];page.on('pageerror',e=>errors.push(e.message));
try{await page.goto('http://127.0.0.1:5975/?desktop=1&engine=clothcraft&testSession=dual-bottom-20261028',{waitUntil:'domcontentloaded'});await page.locator('.main-layout').waitFor();await page.getByRole('combobox',{name:'3D and 2D window arrangement'}).selectOption('2d');
const inner=page.locator('.cc-embedded-root>.exo-grade-inner-bottom-dock'),outer=page.locator('.main-layout>.exo-global-grade-dock-host');await inner.waitFor();await outer.waitFor();
for(const [kind,command,edge] of [['values','grade-table','inner-bottom'],['compare','grade-compare','bottom']]){await page.evaluate(c=>window.dispatchEvent(new CustomEvent('exo-clothcraft-pattern-studio-command',{detail:{command:c}})),command);await page.locator(`.exo-grade-bottom-widget[data-exo-grade-bottom-widget="${kind}"] .exo-grade-widget-placement`).selectOption(edge)}
await page.waitForTimeout(240);const data=await page.evaluate(()=>{const root=document.querySelector('.main-layout'),inner=root.querySelector('.exo-grade-inner-bottom-dock'),outer=root.querySelector(':scope>.exo-global-grade-dock-host');const rect=e=>e.getBoundingClientRect().toJSON();return {inner:rect(inner),outer:rect(outer),innerWidgets:[...inner.querySelectorAll('.exo-grade-bottom-widget--docked')].map(e=>e.dataset.exoGradeBottomWidget),outerWidgets:[...outer.querySelectorAll('.exo-grade-bottom-widget--docked')].map(e=>e.dataset.exoGradeBottomWidget),root:rect(root),toolbarEmbedButtons:[...document.querySelectorAll('[data-exo-grade-action="embed-toolbar"]')].map(e=>e.getAttribute('aria-label'))}});assert.deepEqual(data.innerWidgets,['values']);assert.deepEqual(data.outerWidgets,['compare']);assert(data.outer.width>=data.root.width-2);assert(data.outer.top>=data.inner.bottom-2);assert(data.toolbarEmbedButtons.some(x=>x.includes('Grading Table')));assert(data.toolbarEmbedButtons.some(x=>x.includes('Compare Length')));await page.getByRole('button',{name:'Embed Grading Toolbar in Grading Table'}).click();await page.waitForTimeout(160);const embedded=await page.evaluate(()=>({slot:document.querySelector('[data-exo-grade-toolbar-slot][data-grade-toolbar-parent=values]')?.querySelector('.clo-floating-tool,.exo-quick-grade')?.outerHTML?.slice(0,120)||null,target:document.querySelector('.clo-floating-tool[data-clo-floating-widget=grading-quick-toolbar]')?.parentElement?.getAttribute('data-grade-toolbar-parent')||null}));assert(embedded.slot||embedded.target,`Grading Toolbar not embedded inside Grading Table: ${JSON.stringify(embedded)}`);assert.equal(errors.length,0,errors.join('; '));console.log(JSON.stringify({ok:true,inner:data.innerWidgets,outer:data.outerWidgets,innerWidth:data.inner.width,outerWidth:data.outer.width,toolbarEmbedButtons:data.toolbarEmbedButtons},null,2));}finally{await browser.close()}
